-- Пересчёт рейтингов по одобренным отзывам
UPDATE products p
LEFT JOIN (
    SELECT product_id, ROUND(AVG(rating), 2) AS avg_rating, COUNT(*) AS cnt
      FROM reviews
     WHERE status = 'approved'
     GROUP BY product_id
) r ON r.product_id = p.id
SET p.rating_avg   = COALESCE(r.avg_rating, 0),
    p.rating_count = COALESCE(r.cnt, 0);

