INSERT INTO reviews (product_id, user_id, rating, text, status, is_verified_purchase, moderated_at, created_at) VALUES
(133, 3, 5, 'Беру Морской бриз канистрами по 5 литров для своего аппарата на мойке. Клиенты чаще всего выбирают именно его.', 'approved', 1, '2026-10-02 10:00:00', '2026-10-01 18:20:00'),
(133, 4, 4, 'Хороший свежий аромат, без химозы. Минус звезда — хотелось бы ещё объём 10 л.', 'approved', 0, '2026-10-05 09:00:00', '2026-10-04 21:10:00'),
(151, 5, 5, 'Sauvage — просто восторг. Салон пахнет как дорогой парфюм.', 'approved', 1, '2026-10-07 12:00:00', '2026-10-06 15:45:00'),
(101, 6, 5, 'Купил машину после курильщика. Два раза прогнал Антитабак — запаха табака больше нет. Рекомендую.', 'approved', 1, '2026-10-09 11:00:00', '2026-10-08 19:30:00'),
(152, 2, 5, 'Свежий и ненавязчивый аромат, клиентам нравится.', 'approved', 1, '2026-10-11 10:00:00', '2026-10-10 13:00:00'),
(158, 5, 5, 'Парфюмерная линейка немного дороже, но аромат того стоит.', 'approved', 1, '2026-10-21 10:00:00', '2026-10-20 16:40:00'),
(104, 6, 4, 'Баблгам сладковат для меня, но клиенты-таксисты берут охотно.', 'pending', 0, NULL, '2026-10-27 20:15:00'),
(17, 4, 5, 'Поставили Puff Drive Pro на АЗС в Лиде. Окупился быстрее, чем рассчитывали, поддержка помогла с настройкой ароматов.', 'approved', 1, '2026-10-15 10:00:00', '2026-10-14 17:25:00'),
(16, 3, 4, 'Classic работает без нареканий уже полтора месяца. Хотелось бы инструкцию подробнее, но менеджер всё объяснил по телефону.', 'approved', 0, '2026-10-18 10:00:00', '2026-10-17 11:05:00');
